#!/usr/bin/env bash
# Build the ztmetro status-bar-glyph RRO (target com.android.systemui) and
# verify that the APK contains exactly the 20 drawables SystemUI reads.
#
#   sources : repo/overlay/statusbar-icons/**  (generated by tools/gen_glyphs.py)
#   output  : repo/evidence/statusbar-icons/ztmetro-statusbar-icons-rro.apk
#   host    : local aapt2/android.jar when present, else `ssh hermes-ubuntu`
#             (workdir ~/ztux/icons, SDK ~/android-sdk, JDK ~/android-jdk)
#
# The script is idempotent: it wipes only its own .build dir, reuses the
# throwaway signing key ~/.ztmetro-overlay-debug.keystore, and overwrites the
# APK + dumps. It refuses to finish if the built entry set differs from the
# verified name list (a typo would otherwise be a silent no-op on the phone).
#
# Env overrides: BUILD_LOCAL=1, BUILD_HOST, ANDROID_SDK, ANDROID_JDK,
#                BUILD_TOOLS_VERSION, OUT_DIR, REMOTE_WORK, KEYSTORE.
#
# Usage: repo/scripts/build-overlay-statusbar-icons.sh
set -euo pipefail

_self="${BASH_SOURCE[0]:-}"
if [ -n "$_self" ]; then
  REPO_ROOT="$(cd "$(dirname "$_self")/.." && pwd)"
else
  REPO_ROOT="$(pwd)"
fi

SRC_DIR="${SRC_DIR:-$REPO_ROOT/overlay/statusbar-icons}"
OUT_DIR="${OUT_DIR:-$REPO_ROOT/evidence/statusbar-icons}"
APK_NAME="${APK_NAME:-ztmetro-statusbar-icons-rro.apk}"
BUILD_TOOLS_VERSION="${BUILD_TOOLS_VERSION:-36.0.0}"
ANDROID_SDK="${ANDROID_SDK:-$HOME/android-sdk}"
ANDROID_JDK="${ANDROID_JDK:-$HOME/android-jdk}"
BUILD_HOST="${BUILD_HOST:-hermes-ubuntu}"
REMOTE_WORK="${REMOTE_WORK:-ztux/icons}"
KEYSTORE="${KEYSTORE:-$HOME/.ztmetro-overlay-debug.keystore}"

# Every name must exist in packages/SystemUI/res/drawable*/ and be read by
# SystemUI code; see evidence/statusbar-icons/name-verification.txt.
EXPECTED="
stat_sys_airplane_mode
stat_sys_alarm
stat_sys_alarm_dim
stat_sys_branded_vpn
stat_sys_data_bluetooth_connected
stat_sys_data_bluetooth_connected_battery_0
stat_sys_data_bluetooth_connected_battery_1
stat_sys_data_bluetooth_connected_battery_2
stat_sys_data_bluetooth_connected_battery_3
stat_sys_data_bluetooth_connected_battery_4
stat_sys_data_bluetooth_connected_battery_5
stat_sys_data_bluetooth_connected_battery_6
stat_sys_data_bluetooth_connected_battery_7
stat_sys_data_bluetooth_connected_battery_8
stat_sys_data_bluetooth_connected_battery_9
stat_sys_headset
stat_sys_headset_mic
stat_sys_no_internet_branded_vpn
stat_sys_no_internet_vpn_ic
stat_sys_vpn_ic
"

die() { echo "build-overlay-statusbar-icons: $*" >&2; exit 1; }

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  else
    shasum -a 256 "$1" | awk '{print $1}'
  fi
}

find_tool() { # name -> absolute path
  local n="$1"
  if [ -x "$ANDROID_SDK/build-tools/$BUILD_TOOLS_VERSION/$n" ]; then
    echo "$ANDROID_SDK/build-tools/$BUILD_TOOLS_VERSION/$n"
  elif command -v "$n" >/dev/null 2>&1; then
    command -v "$n"
  else
    die "missing build tool: $n"
  fi
}

check_entries() { # dump-file
  local dump="$1" got want
  got="$(grep -oE 'drawable/[A-Za-z0-9_]+' "$dump" | sed 's|drawable/||' | sort -u)"
  want="$(printf '%s\n' $EXPECTED | sort -u)"
  if [ "$got" != "$want" ]; then
    echo "--- built entries" >&2
    printf '%s\n' "$got" >&2
    echo "--- expected entries" >&2
    printf '%s\n' "$want" >&2
    die "resource set does not match the verified name list"
  fi
  echo "entry check: $(printf '%s\n' "$got" | wc -l | tr -d ' ') drawables, exact match"
}

build_all() {
  export JAVA_HOME="$ANDROID_JDK"
  PATH="$ANDROID_JDK/bin:$PATH"
  export PATH
  command -v keytool >/dev/null 2>&1 || die "keytool not found (set ANDROID_JDK)"
  command -v java >/dev/null 2>&1 || die "java not found (set ANDROID_JDK)"
  local androidjar="$ANDROID_SDK/platforms/android-36/android.jar"
  [ -f "$androidjar" ] || die "missing $androidjar"
  [ -d "$SRC_DIR/res/drawable" ] || die "missing $SRC_DIR/res/drawable"
  local AAPT2 ZIPALIGN APKSIGNER KEYTOOL
  AAPT2="$(find_tool aapt2)"
  ZIPALIGN="$(find_tool zipalign)"
  APKSIGNER="$(find_tool apksigner)"
  KEYTOOL="$(find_tool keytool)"

  local work="$OUT_DIR/.build"
  rm -rf "$work" && mkdir -p "$work" "$OUT_DIR"

  echo "== compile =="
  "$AAPT2" compile --dir "$SRC_DIR/res" -o "$work/res.zip"

  echo "== link =="
  if ! "$AAPT2" link \
    -o "$work/unsigned.apk" \
    -I "$androidjar" \
    --manifest "$SRC_DIR/AndroidManifest.xml" \
    --min-sdk-version 34 \
    --target-sdk-version 36 \
    --no-resource-deduping \
    --no-resource-removal \
    "$work/res.zip" > "$work/link.log" 2>&1; then
    cat "$work/link.log" >&2
    die "aapt2 link failed"
  fi
  grep -E 'error|warning' "$work/link.log" || true

  echo "== align =="
  "$ZIPALIGN" -p -f 4 "$work/unsigned.apk" "$work/aligned.apk"

  echo "== sign (throwaway key: $KEYSTORE) =="
  if [ ! -f "$KEYSTORE" ]; then
    "$KEYTOOL" -genkeypair -keystore "$KEYSTORE" -alias ztmetro \
      -storepass ztmetro -keypass ztmetro -keyalg RSA -keysize 2048 -validity 3650 \
      -dname "CN=ztmetro overlay (throwaway)" >/dev/null 2>&1
  fi
  "$APKSIGNER" sign --ks "$KEYSTORE" --ks-pass pass:ztmetro --key-pass pass:ztmetro \
    --min-sdk-version 34 --v4-signing-enabled false \
    --out "$OUT_DIR/$APK_NAME" "$work/aligned.apk"
  rm -f "$OUT_DIR/$APK_NAME.idsig"

  echo "== verify =="
  "$APKSIGNER" verify --min-sdk-version 34 --print-certs \
    "$OUT_DIR/$APK_NAME" > "$OUT_DIR/apksigner-verify.txt" 2>&1
  cat "$OUT_DIR/apksigner-verify.txt"

  "$AAPT2" dump badging "$OUT_DIR/$APK_NAME" > "$OUT_DIR/aapt2-dump-badging.txt"
  "$AAPT2" dump resources "$OUT_DIR/$APK_NAME" > "$OUT_DIR/aapt2-dump-resources.txt"
  grep -E '^(package|overlay|application)' "$OUT_DIR/aapt2-dump-badging.txt" || true
  check_entries "$OUT_DIR/aapt2-dump-resources.txt"

  echo "== APK =="
  printf 'APK    %s\nsha256 %s\n' "$OUT_DIR/$APK_NAME" "$(sha256_of "$OUT_DIR/$APK_NAME")"
  printf 'entries: %s\n' "$(unzip -l "$OUT_DIR/$APK_NAME" | tail -1 | tr -s ' ')"
  rm -rf "$work"
}

if [ "${REMOTE_CHILD:-0}" = "1" ]; then
  build_all
  exit 0
fi

if [ "${BUILD_LOCAL:-0}" = "1" ] || \
   { [ -x "$ANDROID_SDK/build-tools/$BUILD_TOOLS_VERSION/aapt2" ] && \
     [ -f "$ANDROID_SDK/platforms/android-36/android.jar" ]; }; then
  echo "== building locally ($ANDROID_SDK/build-tools/$BUILD_TOOLS_VERSION) =="
  build_all
else
  echo "== no local aapt2/android.jar: building on $BUILD_HOST (~/$REMOTE_WORK) =="
  command -v ssh >/dev/null 2>&1 || die "ssh required for the remote build"
  command -v rsync >/dev/null 2>&1 || die "rsync required for the remote build"
  ssh "$BUILD_HOST" "mkdir -p ~/$REMOTE_WORK/src ~/$REMOTE_WORK/out"
  rsync -a --delete "$SRC_DIR/." "$BUILD_HOST:$REMOTE_WORK/src/"
  ssh "$BUILD_HOST" \
    "REMOTE_CHILD=1 \
     SRC_DIR=\$HOME/$REMOTE_WORK/src OUT_DIR=\$HOME/$REMOTE_WORK/out \
     ANDROID_SDK=\$HOME/android-sdk ANDROID_JDK=\$HOME/android-jdk \
     BUILD_TOOLS_VERSION='$BUILD_TOOLS_VERSION' APK_NAME='$APK_NAME' \
     KEYSTORE=\$HOME/.ztmetro-overlay-debug.keystore \
     bash -s" < "${BASH_SOURCE[0]}"
  mkdir -p "$OUT_DIR"
  rsync -a --exclude '.build' "$BUILD_HOST:$REMOTE_WORK/out/" "$OUT_DIR/"
  echo
  echo "== APK =="
  printf 'APK    %s\nsha256 %s\n' "$OUT_DIR/$APK_NAME" "$(sha256_of "$OUT_DIR/$APK_NAME")"
fi
